def transform(grid):
    h, w = len(grid), len(grid[0])

    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_seps = set(divider_rows)
    col_seps = set(divider_cols)
    cells = [grid[r][c] for r in range(h) for c in range(w)
             if r not in row_seps and c not in col_seps]
    bg = max(set(cells), key=cells.count)

    def segments(n, separators):
        result = []
        start = 0
        for i in range(n):
            if i in separators:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    rows = segments(h, row_seps)
    cols = segments(w, col_seps)

    best = None
    best_score = -1
    for r0, r1 in rows:
        for c0, c1 in cols:
            score = sum(grid[r][c] != bg
                        for r in range(r0, r1) for c in range(c0, c1))
            if score > best_score:
                best_score = score
                best = (r0, r1, c0, c1)

    r0, r1, c0, c1 = best
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]
    out = [row[:] for row in grid]
    for a, b in rows:
        for x, y in cols:
            for dr in range(b - a):
                for dc in range(y - x):
                    out[a + dr][x + dc] = pattern[dr][dc]
    return out
